%[text] %[text:anchor:H_0AAABA39] ## Local Helper Functions
%[text] If you wish to see the details of the code, select the **View** tab and switch to **Output Inline**. Alternately, select **Output inline** using the icon ![live script output inline icon](text:image:5ea9) at the top right of the Live Editor pane.
function pfC = DrawFamily(xVals,FxVals)
try
    pf = plot(xVals,FxVals,"LineWidth",3,SeriesIndex="none");
catch
    pf = plot(xVals,FxVals,"k","LineWidth",3);
end
    hold on
    pfC = copyobj(pf,pf.Parent);
    pfC.Color = [1 0 0];
    pfC.Parent.YLim = [min(double(FxVals))-8 max(double(FxVals))+8];
    Copts = [-10:.5:-.5 .5:.5:10];
    FVals = FxVals+Copts';
    plot(pf.Parent,xVals,FVals,"LineWidth",1,SeriesIndex=1);
    hold off
title("Plotting the family of antiderivatives $F(x)+C$","Interpreter","latex")
subtitle(pfC.Parent,"$C = $"+0,"Interpreter","latex");
legend(pf.Parent,["F(x)" "F(x)+C" "Family of F(x)"],"Location","bestoutside")
end

